// ─────────────────────────────────────────────────────────────────────────────
// Main Component
// ─────────────────────────────────────────────────────────────────────────────

/**
 * @component PageLoader
 * @description Hiển thị trạng thái loading với 4 biến thể (Full Splash Screen, Minimal, Bar, Inline).
 */
export const PageLoader = forwardRef(
  (
    {
      variant = 'full',
      fixed = true,
      transparent = false,
      text = 'Đang chuẩn bị trải nghiệm điện ảnh đỉnh cao...',
      className = '',
    },
    ref
  ) => {
    // 1. Biến thể Thanh tiến trình (Bar)
    if (variant === 'bar') {
      return (
        <div
          ref={ref}
          className={classNames('page-loader__bar', className)}
          role="status"
          aria-label="Đang tải trang"
          aria-live="polite"
        >
          <div className="page-loader__bar-track" aria-hidden="true" />
          <span className="page-loader__sr-text">Đang tải trang...</span>
        </div>
      );
    }

    // 2. Biến thể Trong dòng (Inline)
    if (variant === 'inline') {
      return (
        <span
          ref={ref}
          className={classNames('page-loader__inline', className)}
          role="status"
          aria-label="Đang xử lý"
          aria-live="polite"
        >
          <span className="page-loader__inline-dot" aria-hidden="true" />
          <span className="page-loader__inline-dot" aria-hidden="true" />
          <span className="page-loader__inline-dot" aria-hidden="true" />
          <span className="page-loader__sr-text">Đang xử lý...</span>
        </span>
      );
    }

    // 3. Biến thể Tối giản (Minimal)
    if (variant === 'minimal') {
      return (
        <div
          ref={ref}
          className={classNames('page-loader', 'page-loader--minimal', className, {
            'page-loader--fixed': fixed,
            'page-loader--transparent': transparent,
          })}
          role="status"
          aria-label="Đang tải dữ liệu"
          aria-live="polite"
        >
          <div className="page-loader__spinner">
            <div className="page-loader__spinner-ring" aria-hidden="true" />
            <div className="page-loader__spinner-core" aria-hidden="true" />
          </div>
          <span className="page-loader__sr-text">Đang tải...</span>
        </div>
      );
    }

    // 4. Biến thể Toàn màn hình (Full Splash Screen)
    return (
      <div
        ref={ref}
        className={classNames('page-loader', 'page-loader--full', className, {
          'page-loader--fixed': fixed,
          'page-loader--transparent': transparent,
        })}
        role="status"
        aria-label="Đang tải ứng dụng Sạp Phim"
        aria-live="polite"
      >
        <div className="page-loader__content">
          <div className="page-loader__logo-wrapper">
            <SapPhimInlineLogo />
          </div>
          <div className="page-loader__spinner">
            <div className="page-loader__spinner-ring" aria-hidden="true" />
            <div className="page-loader__spinner-core" aria-hidden="true" />
          </div>
          {text && <p className="page-loader__quote">{text}</p>}
        </div>
        <span className="page-loader__sr-text">{text || 'Đang tải ứng dụng Sạp Phim...'}</span>
      </div>
    );
  }
);

PageLoader.displayName = 'PageLoader';

PageLoader.propTypes = {
  /**
   * Biến thể hiển thị:
   * - `full`    — Splash screen toàn màn hình với Logo Sạp Phim
   * - `minimal` — Spinner căn giữa container
   * - `bar`     — Thanh tiến trình chạy trên đỉnh trang
   * - `inline`  — 3 dấu chấm động nhịp nhàng (dùng trong text/button)
   */
  variant: PropTypes.oneOf(['full', 'minimal', 'bar', 'inline']),
  /** Cố định vị trí (position: fixed) */
  fixed: PropTypes.bool,
  /** Hiệu ứng nền mờ glassmorphism */
  transparent: PropTypes.bool,
  /** Dòng chữ thông báo bên dưới spinner (áp dụng cho variant='full') */
  text: PropTypes.string,
  /** CSS class bổ sung */
  className: PropTypes.string,
};

export default memo(PageLoader);
